  const GEMS = [{"id": "gem-anxoveres", "pattern": "anchovy", "tag": "Empordà gem · born here", "name": "The anxoveres", "story": "For generations the anchovy of L’Escala went through women’s hands: they packed the fish in salt, came back months later to clean it, and lifted each fillet off the bone one at a time. The craft passed from mother to daughter, and the town still calls the women who do it anxoveres.", "where": "The salter’s own counter in L’Escala, in the tables."}, {"id": "gem-cremat", "pattern": "cremat", "tag": "Coast gem · born here", "name": "Rum from the Cuba run", "story": "Catalan sailors and traders on the Cuba run brought home dark rum and the songs of Havana. Burned in a clay pot on the beach, the rum became the coast’s own drink and the songs its own music, and on summer nights at Calella the two still arrive together.", "where": "The havaneres night on the beach at Calella de Palafrugell, in July."}, {"id": "gem-recuit", "pattern": "recuit", "tag": "Empordà gem · born here", "name": "Curd in a cloth", "story": "Before refrigeration, a farmhouse that had milk and no market made recuit: the curd set slowly overnight and hung in a cloth to drain, eaten within a day or two with the honey of the same farm. It is still made that way in the Empordà, and it still keeps only a few days.", "where": "Girona’s covered market, and the dessert line of the village houses."}];
